/* Academic Cat V6.8.2 - long-term storage protection */
const V68_VERSION='6.8.2';
const V68_DB_NAME='AcademicCatThesisDB';
const V68_DB_VERSION=3;
const V68_STORE_KEYS=['chapters','writingLogs','writingRoutes','problems','feedback','literature','figures','milestones','todos','versions','defense','focusLogs','meetings','finalChecks'];
const V68_ALL_STORES=['state','images','snapshots','trash','meta','config',...V68_STORE_KEYS,'imagesMeta','imageBlobs','drafts','searchIndex','errorLogs'];
let v68db=null,v68DbReady=false,v68Booting=false,v68Loaded=new Set(),v68FullLoaded=new Set(),v68Counts={},v68NavStack=[],v68ActiveDraftKey='',v68AnalyticsWorker=null,v68ImageWorker=null,v68WorkerSeq=0,v68PersistTimer=null,v68LastBackupCheck=null,v681RecordSig={},v681ImageStats=null;

function v68Req(req){return new Promise((res,rej)=>{req.onsuccess=()=>res(req.result);req.onerror=()=>rej(req.error||new Error('IndexedDB request failed'))})}
function v68TxDone(tx){return new Promise((res,rej)=>{tx.oncomplete=()=>res();tx.onerror=()=>rej(tx.error||new Error('IndexedDB transaction failed'));tx.onabort=()=>rej(tx.error||new Error('IndexedDB transaction aborted'))})}
function v681DecorateRecord(name,x){
 if(!x||typeof x!=='object')return x;
 const v=Object.assign({},x);
 if(name==='problems')v._active=v.status==='已解决'?'done':'open';
 else if(name==='feedback')v._active=v.status==='已完成'?'done':'open';
 else if(name==='todos')v._active=v.done?'done':'open';
 return v
}
function v68EnsureIndexes(store,name){
 const add=(n,key,opt={})=>{if(!store.indexNames.contains(n))store.createIndex(n,key,opt)};
 add('updatedAt','updatedAt'); add('createdAt','createdAt');
 if(['writingLogs','writingRoutes','focusLogs','meetings','milestones','versions'].includes(name))add('date','date');
 if(['writingLogs','writingRoutes'].includes(name))add('chapterId','chapterId');
 if(['problems','feedback','figures','defense','milestones'].includes(name))add('status','status');
 if(['problems','feedback','todos'].includes(name)){add('_active','_active');add('priority','priority');add('activePriority',['_active','priority'])}
 if(name==='problems')add('resolvedAt','resolvedAt');
 if(['feedback','todos'].includes(name))add('completedAt','completedAt');
 if(name==='todos')add('due','due');
 if(name==='literature'){add('status','status');add('year','year');add('doi','doi')}
}
function v681UpgradeDerivedFields(st,name){
 if(!['problems','feedback','todos'].includes(name))return;
 const r=st.openCursor();r.onsuccess=()=>{const c=r.result;if(!c)return;const next=v681DecorateRecord(name,c.value);if(next._active!==c.value._active)c.update(next);c.continue()}
}
function openV68DB(){
 if(v68DbReady&&v68db)return Promise.resolve(v68db);
 return new Promise((resolve,reject)=>{
  if(!('indexedDB' in window)){reject(new Error('IndexedDB unavailable'));return}
  const req=indexedDB.open(V68_DB_NAME,V68_DB_VERSION);
  req.onupgradeneeded=()=>{
   const db=req.result;
   for(const name of V68_ALL_STORES){
    let st;
    if(!db.objectStoreNames.contains(name))st=db.createObjectStore(name,{keyPath:(name==='state'||name==='meta'||name==='config')?'key':'id'});else st=req.transaction.objectStore(name);
    if(V68_STORE_KEYS.includes(name)){v68EnsureIndexes(st,name);v681UpgradeDerivedFields(st,name)}
    if(name==='imagesMeta'){if(!st.indexNames.contains('createdAt'))st.createIndex('createdAt','createdAt');if(!st.indexNames.contains('ownerType'))st.createIndex('ownerType','ownerType');if(!st.indexNames.contains('owner'))st.createIndex('owner',['ownerType','ownerId']);if(!st.indexNames.contains('ownerCreatedAt'))st.createIndex('ownerCreatedAt',['ownerType','ownerId','createdAt']);if(!st.indexNames.contains('ownerTypeCreatedAt'))st.createIndex('ownerTypeCreatedAt',['ownerType','createdAt']);if(!st.indexNames.contains('hash'))st.createIndex('hash','hash')}
    if(name==='searchIndex'){if(!st.indexNames.contains('module'))st.createIndex('module','module');if(!st.indexNames.contains('updatedAt'))st.createIndex('updatedAt','updatedAt');if(!st.indexNames.contains('tokens'))st.createIndex('tokens','tokens',{multiEntry:true})}
    if(name==='snapshots'&&!st.indexNames.contains('ts'))st.createIndex('ts','ts');
    if(name==='trash'&&!st.indexNames.contains('deletedAt'))st.createIndex('deletedAt','deletedAt');
   }
  };
  req.onsuccess=()=>{v68db=req.result;v68DbReady=true;academicDB=v68db;dbReady=true;v68db.onversionchange=()=>v68db.close();resolve(v68db)};
  req.onerror=()=>reject(req.error||new Error('V6.8.2 database open failed'));
 });
}
function v68Store(name,mode='readonly'){if(!v68db)throw new Error('V6.8.2 DB not ready');return v68db.transaction(name,mode).objectStore(name)}
async function v68Get(store,key){return v68Req(v68Store(store).get(key))}
async function v68GetAll(store){return v68Req(v68Store(store).getAll())}
async function v68Put(store,value){const v=V68_STORE_KEYS.includes(store)?v681DecorateRecord(store,value):value;try{return await v68Req(v68Store(store,'readwrite').put(v))}catch(e){if(typeof v682HandleQuotaExceeded==='function'&&v682IsQuotaError(e))v682HandleQuotaExceeded(e,store);throw e}}
async function v68Delete(store,key){return v68Req(v68Store(store,'readwrite').delete(key))}
async function v68Clear(store){return v68Req(v68Store(store,'readwrite').clear())}
async function v68Count(store){return v68Req(v68Store(store).count())}
async function v68Query(store,indexName,range,direction='next',limit=0){
 const st=v68Store(store),source=indexName?st.index(indexName):st,out=[];
 return new Promise((res,rej)=>{const r=source.openCursor(range||null,direction);r.onerror=()=>rej(r.error);r.onsuccess=()=>{const c=r.result;if(!c||limit&&out.length>=limit){res(out);return}out.push(c.value);c.continue()}})
}
function v681MergeUnique(...groups){const m=new Map();for(const arr of groups)for(const x of arr||[])if(x?.id)m.set(x.id,x);return [...m.values()]}
async function v681UnionQueries(store,queries=[]){const groups=[];for(const q of queries)groups.push(await v68Query(store,q.index||null,q.range||null,q.direction||'next',q.limit||0));return v681MergeUnique(...groups)}
function v681RecordFingerprint(x){if(!x)return'';return JSON.stringify(x)}
function v681TrackLoaded(name,arr,full){if(!v681RecordSig[name]||full)v681RecordSig[name]=new Map();const m=v681RecordSig[name];for(const x of arr||[])if(x?.id)m.set(x.id,v681RecordFingerprint(x))}

// Let legacy helpers point to the V6.8.2 database for snapshot/trash compatibility.
openAcademicDB=openV68DB;

async function v68ReadOldStore(dbName,store,key){return new Promise(resolve=>{try{const r=indexedDB.open(dbName);r.onerror=()=>resolve(null);r.onsuccess=()=>{const db=r.result;if(!db.objectStoreNames.contains(store)){db.close();resolve(null);return}const tx=db.transaction(store),st=tx.objectStore(store),q=key===undefined?st.getAll():st.get(key);q.onsuccess=()=>{const x=q.result;db.close();resolve(x)};q.onerror=()=>{db.close();resolve(null)}}}catch(e){resolve(null)}})}
async function v68SnapshotRaw(label,rawState){await v68Put('snapshots',{id:uid(),ts:Date.now(),label,state:clone(rawState),kind:'migration'})}
async function v68ReplaceStore(name,arr){
 try{const tx=v68db.transaction(name,'readwrite'),st=tx.objectStore(name);st.clear();for(const x of arr||[])st.put(V68_STORE_KEYS.includes(name)?v681DecorateRecord(name,x):x);await v68TxDone(tx);if(V68_STORE_KEYS.includes(name))v681TrackLoaded(name,arr||[],true)}catch(e){if(typeof v682HandleQuotaExceeded==='function'&&v682IsQuotaError(e))v682HandleQuotaExceeded(e,name);throw e}
}
async function v68WriteFullState(raw,{compat=true}={}){
 const n=normalize(raw); await v68Put('config',{key:'settings',value:clone(n.settings)});await v68Put('config',{key:'ui',value:clone(n.ui)});
 for(const k of V68_STORE_KEYS)await v68ReplaceStore(k,clone(n[k]||[]));
 if(compat)await v68Put('state',{key:'main',value:clone(n),updatedAt:nowStamp(),compat:true});
 await v68UpdateCounts(); return n;
}
async function v68UpdateCounts(){const pairs=await Promise.all(V68_STORE_KEYS.map(async k=>[k,await v68Count(k)]));v68Counts=Object.fromEntries(pairs);return v68Counts}

function v68MainFallbackState(){try{return normalize(state)}catch(e){return normalize(clone(defaults))}}
async function v68MigrateIfNeeded(){
 const done=await v68Get('meta','schema'); if(done?.value?.version>=2)return;
 let source=(await v68ReadOldStore('AcademicCatThesisDBV66','state','main'))?.value||v68MainFallbackState(); source=normalize(source);
 await v68SnapshotRaw('V6.7 → V6.8.2 数据库升级前快照',source);
 await v68WriteFullState(source);
 // Copy old images into metadata/blob split stores; the old database is intentionally kept untouched.
 const oldImages=await v68ReadOldStore('AcademicCatThesisDBV66','images');
 if(Array.isArray(oldImages)){for(const img of oldImages){try{await v68ImportLegacyImage(img)}catch(e){v68LogError('image-migration',e)}}}
 const oldSnaps=await v68ReadOldStore('AcademicCatThesisDBV66','snapshots');if(Array.isArray(oldSnaps))for(const x of oldSnaps)if(!(await v68Get('snapshots',x.id)))await v68Put('snapshots',x);
 const oldTrash=await v68ReadOldStore('AcademicCatThesisDBV66','trash');if(Array.isArray(oldTrash))for(const x of oldTrash)if(!(await v68Get('trash',x.id)))await v68Put('trash',x);
 await v68Put('meta',{key:'schema',value:{version:2,appVersion:V68_VERSION,migratedAt:nowStamp(),source:'V6.7/AcademicCatThesisDBV66',verified:true,oldDatabasePreserved:true}});
 await v68Put('meta',{key:'lastKnownGood',value:{at:nowStamp(),version:2}});
 await v681RecomputeImageStats();await v68RebuildSearchIndex();
}

async function v68ImportLegacyImage(img){
 if(!img?.id)return;const blob=img.blob instanceof Blob?img.blob:null;const processed=blob?await v68ProcessImage(blob):{};
 const meta={id:img.id,name:img.name||'图片',type:img.type||blob?.type||'',size:Number(img.size||blob?.size||0),ownerType:img.ownerType||'',ownerId:img.ownerId||'',ownerLabel:img.ownerLabel||'',createdAt:img.createdAt||Date.now(),hash:processed.hash||img.hash||'',thumbSize:processed.thumbnail?.size||0};
 await v68Put('imagesMeta',meta);if(blob)await v68Put('imageBlobs',{id:img.id,blob,thumbnail:processed.thumbnail||null})
}

async function v68LoadConfig(){const s=await v68Get('config','settings'),u=await v68Get('config','ui'),chs=await v68GetAll('chapters'),checks=await v68GetAll('finalChecks');state=normalize({settings:s?.value||state.settings,ui:u?.value||state.ui,chapters:chs,finalChecks:checks});v68Loaded=new Set(['chapters','finalChecks']);v68FullLoaded=new Set(['chapters','finalChecks']);v681TrackLoaded('chapters',chs,true);v681TrackLoaded('finalChecks',checks,true);ensureCurrentState();restoreUIState()}
async function v68LoadStore(name,{range=null,index=null,full=true,direction='next',limit=0}={}){let arr;if(range||index)arr=await v68Query(name,index,range,direction,limit);else arr=await v68GetAll(name);state[name]=arr||[];v68Loaded.add(name);if(full)v68FullLoaded.add(name);else v68FullLoaded.delete(name);v681TrackLoaded(name,state[name],full);return state[name]}
async function v68LoadHomeData(){
 const today=iso(),start=addDays(today,-45),end=addDays(today,1);
 await v68LoadStore('writingLogs',{index:'date',range:IDBKeyRange.bound(start,end,false,true),full:false});
 await v68LoadStore('writingRoutes',{index:'date',range:IDBKeyRange.only(today),full:false});
 for(const k of ['problems','feedback','todos']){
  const open=await v68Query(k,'_active',IDBKeyRange.only('open'),'next');
  const recent=await v68Query(k,'updatedAt',null,'prev',8);
  state[k]=v681MergeUnique(open,recent);v68Loaded.add(k);v68FullLoaded.delete(k);v681TrackLoaded(k,state[k],false)
 }
 for(const [k,idx] of [['meetings','date'],['versions','date'],['defense','updatedAt']]){
  state[k]=await v68Query(k,idx,null,'prev',8);v68Loaded.add(k);v68FullLoaded.delete(k);v681TrackLoaded(k,state[k],false)
 }
 await v68UpdateCounts();
}
function v68StatsBounds(){const a=dateObj(statsAnchor);let start,end;if(statsRange==='today'){start=addDays(statsAnchor,-1);end=addDays(statsAnchor,2)}else if(statsRange==='week'){const d=dateObj(statsAnchor),wd=(d.getDay()+6)%7;d.setDate(d.getDate()-wd-7);start=localISO(d);end=addDays(start,21)}else if(statsRange==='month'){const d=dateObj(statsAnchor);d.setMonth(d.getMonth()-1,1);start=localISO(d);const e=dateObj(statsAnchor);e.setMonth(e.getMonth()+2,1);end=localISO(e)}else if(statsRange==='year'){const y=dateObj(statsAnchor).getFullYear();start=`${y-1}-01-01`;end=`${y+2}-01-01`}else return null;return {start,end}}
async function v681LoadStatsLifecycle(store,b,doneIndex){
 const range=IDBKeyRange.bound(b.start,b.end,false,true),queries=[{index:'createdAt',range},{index:'updatedAt',range},{index:'_active',range:IDBKeyRange.only('open')}];if(doneIndex)queries.push({index:doneIndex,range});
 const arr=await v681UnionQueries(store,queries);state[store]=arr;v68Loaded.add(store);v68FullLoaded.delete(store);v681TrackLoaded(store,arr,false)
}
async function v681LoadStatsDetail(b){if(!state.ui.statsDetailed||!b)return;const range=IDBKeyRange.bound(b.start,b.end,false,true);for(const k of ['literature','figures','defense']){const arr=await v68Query(k,'updatedAt',range);state[k]=arr;v68Loaded.add(k);v68FullLoaded.delete(k);v681TrackLoaded(k,arr,false)}for(const k of ['meetings','milestones','versions']){const arr=await v68Query(k,'date',range);state[k]=arr;v68Loaded.add(k);v68FullLoaded.delete(k);v681TrackLoaded(k,arr,false)}}
async function v68LoadStatsData(){
 const b=v68StatsBounds();
 if(!b){for(const k of ['writingLogs','focusLogs','problems','feedback','todos','meetings'])await v68LoadStore(k,{full:true});if(state.ui.statsDetailed)for(const k of ['literature','figures','milestones','versions','defense'])await v68LoadStore(k,{full:true});return}
 const range=IDBKeyRange.bound(b.start,b.end,false,true);
 await v68LoadStore('writingLogs',{index:'date',range,full:false});await v68LoadStore('focusLogs',{index:'date',range,full:false});
 await v681LoadStatsLifecycle('problems',b,'resolvedAt');await v681LoadStatsLifecycle('feedback',b,'completedAt');
 const todos=await v681UnionQueries('todos',[{index:'updatedAt',range},{index:'completedAt',range}]);state.todos=todos;v68Loaded.add('todos');v68FullLoaded.delete('todos');v681TrackLoaded('todos',todos,false);
 await v68LoadStore('meetings',{index:'date',range,full:false});await v681LoadStatsDetail(b)
}
async function v68EnsureViewData(view){
 if(view==='home')return v68LoadHomeData(); if(view==='chapters'||view==='focus'){await v68LoadStore('writingRoutes',{index:'date',range:IDBKeyRange.only(iso()),full:false});return}
 if(view==='problems'){await v68LoadStore('problems',{full:true});await v68LoadStore('literature',{full:true});await v68LoadStore('feedback',{full:true});return}
 if(view==='stats')return v68LoadStatsData(); if(view==='settings')return v68UpdateCounts(); if(view==='resources')return v68EnsureResourceData();
}
async function v68EnsureResourceData(){const map={literature:'literature',todos:'todos',feedback:'feedback',meetings:'meetings',figures:'figures',milestones:'milestones',versions:'versions',finalcheck:'finalChecks',defense:'defense'};const k=map[resourceTab];if(k)await v68LoadStore(k,{full:true});if(resourceTab==='finalcheck'){await v68LoadStore('figures',{full:true});await v68LoadStore('problems',{full:true});await v68LoadStore('literature',{full:true})}}

function v68StoreArraySignature(arr){if(!Array.isArray(arr))return '';let h=2166136261;for(const x of arr){const s=`${x?.id||''}|${x?.updatedAt||x?.createdAt||x?.date||''}|${x?.title||x?.name||x?.topic||''}|${x?.status??x?.done??''}|${x?.words??x?.currentWords??''}`;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)}}return `${arr.length}|${h>>>0}`}
let v68PersistSig={};
async function v681DeleteSearchForRecord(store,id){const map={writingLogs:'写作记录',writingRoutes:'写作路线',problems:'问题',literature:'文献',feedback:'修改',todos:'待办',meetings:'会议',figures:'图表',milestones:'节点',versions:'版本',defense:'答辩'};if(store==='chapters'){for(const mod of ['章节','小节','章节任务']){const arr=await v68Query('searchIndex','module',IDBKeyRange.only(mod));for(const e of arr)if(e.recordId===id||String(e.recordId||'').startsWith(id+'::'))await v68Delete('searchIndex',e.id)}return}const mod=map[store];if(mod)await v68Delete('searchIndex',`${mod}:${id}`)}
async function v681UpsertSearchForRecord(store,record){if(!record?.id||!['chapters','writingLogs','writingRoutes','problems','literature','feedback','todos','meetings','figures','milestones','versions','defense'].includes(store))return;await v681DeleteSearchForRecord(store,record.id);let entries=[];try{entries=await v68WorkerRequest(v68AnalyticsWorker,'searchIndex',{[store]:[record]},6000)}catch(e){}for(const e of entries||[]){e.tokens=v68Tokenize(`${e.title} ${e.text}`);await v68Put('searchIndex',e)}}
async function v681RefreshSearchMeta(){const count=await v68Count('searchIndex');await v68Put('meta',{key:'searchIndex',value:{builtAt:nowStamp(),count,strategy:'incremental-v681'}})}
async function v68PersistLoaded(){
 if(!v68DbReady)return;await v68Put('config',{key:'settings',value:clone(state.settings)});await v68Put('config',{key:'ui',value:clone(state.ui)});let searchTouched=false;
 for(const k of V68_STORE_KEYS){const arr=state[k]||[];if(!v68Loaded.has(k)&&!arr.length)continue;const sig=v68StoreArraySignature(arr);if(sig===v68PersistSig[k])continue;const oldMap=v681RecordSig[k]||new Map(),changed=arr.filter(x=>oldMap.get(x.id)!==v681RecordFingerprint(x)),deleted=v68FullLoaded.has(k)?[...oldMap.keys()].filter(id=>!arr.some(x=>x.id===id)):[];
  if(v68FullLoaded.has(k))await v68ReplaceStore(k,clone(arr));else{const tx=v68db.transaction(k,'readwrite'),st=tx.objectStore(k);for(const x of arr)st.put(v681DecorateRecord(k,clone(x)));await v68TxDone(tx);v681TrackLoaded(k,arr,false)}
  for(const x of changed){await v681UpsertSearchForRecord(k,x);searchTouched=true}for(const id of deleted){await v681DeleteSearchForRecord(k,id);searchTouched=true}v68PersistSig[k]=sig;
 }
 await v68Put('state',{key:'main',value:{settings:clone(state.settings),ui:clone(state.ui),chapters:clone(state.chapters),updatedAt:nowStamp()},updatedAt:nowStamp(),compat:'compact'});await v68Put('meta',{key:'lastWrite',value:nowStamp()});if(searchTouched)await v681RefreshSearchMeta()
}
function save(options={}){ensureCurrentState();persistUIState();try{localStorage.setItem('academicCatV68Recovery',JSON.stringify({version:V68_VERSION,settings:state.settings,ui:state.ui,chapters:state.chapters,at:nowStamp()}))}catch(e){}clearTimeout(v68PersistTimer);v68PersistTimer=setTimeout(()=>v68PersistLoaded().catch(e=>v68LogError('persist',e)),40);maybeSnapshot();v68ClearActiveDraft();if(options.render!==false)renderAll()}

function saveWritingLog(id){const old=state.writingLogs.find(x=>x.id===id),words=+$('#f-words').value||0,minutes=+$('#f-min').value||0,cid=$('#f-ch').value,sid=$('#f-sec').value;if(words<=0)return alert('请填写本次新增字数');if(old)applyWritingDelta(old.chapterId,old.sectionId,-Number(old.words||0));applyWritingDelta(cid,sid,words);const workDate=$('#f-date').value,times=auditFields(old,workDate);const v={id:id||uid(),date:workDate,chapterId:cid,sectionId:sid,words,minutes,note:$('#f-note').value.trim(),...times};const i=state.writingLogs.findIndex(x=>x.id===id);if(i>=0)state.writingLogs[i]=v;else state.writingLogs.push(v);if(!old&&minutes>0){const ft=auditFields(null,workDate);state.focusLogs.push({id:uid(),date:v.date,minutes,task:v.note,...ft});v68Loaded.add('focusLogs')}if(!old&&workDate===iso()){const route=state.writingRoutes.find(r=>!r.done&&r.date===workDate&&r.chapterId===cid&&(!r.sectionId||r.sectionId===sid));if(route){route.done=true;route.updatedAt=nowStamp();route.completedAt=route.updatedAt}}state.settings.lastUsedChapterId=cid;state.settings.lastUsedSectionId=sid;v68Loaded.add('writingLogs');v68Loaded.add('chapters');closeSheet();save();go('home')}

function setStatsRange(range){statsRange=range;if(range!=='all'){statsAnchor=iso();calendarCursor=dateObj(statsAnchor);calendarCursor.setDate(1)}persistUIState();go('stats',{replace:true})}
function setStatsAnchor(v){if(!v)return;statsAnchor=dateOnly(v);calendarCursor=dateObj(statsAnchor);calendarCursor.setDate(1);persistUIState();go('stats',{replace:true})}
function moveStatsPeriod(n){if(statsRange==='all')return;const d=dateObj(statsAnchor);if(statsRange==='today')d.setDate(d.getDate()+n);else if(statsRange==='week')d.setDate(d.getDate()+7*n);else if(statsRange==='month')d.setMonth(d.getMonth()+n);else if(statsRange==='year')d.setFullYear(d.getFullYear()+n);statsAnchor=localISO(d);calendarCursor=dateObj(statsAnchor);calendarCursor.setDate(1);persistUIState();go('stats',{replace:true})}
toggleStatsDetail=async function(){ensureCoreState();state.ui.statsDetailed=!state.ui.statsDetailed;await v68LoadStatsData();save({render:false});renderStats();v68RequestStatsWorker()}

function renderCurrentViewV68(view=currentView){
 if(view==='home'){renderHome();const h=$('#view-home');if(h&&!h.querySelector('.stage-card'))h.insertAdjacentHTML('afterbegin',stageFocusHTML())}
 else if(view==='chapters')renderChapters();else if(view==='problems')renderProblems();else if(view==='resources')renderResources();else if(view==='stats'){renderStats();v68RequestStatsWorker()}else if(view==='settings')renderSettings();else if(view==='focus')renderFocus();updatePageIntro(view);$('#fab').onclick=quickAddMenu;$('#fab').style.display=(view==='stats'||view==='settings')?'none':'block';v68UpdateBackButton()
}
