async function go(view,opts={}){rememberScroll(currentView);if(!opts.fromBack&&view!==currentView){v68NavStack.push({view:currentView,scroll:window.scrollY||0,resourceTab,statsRange,statsAnchor});if(v68NavStack.length>30)v68NavStack.shift()}currentView=view;$$('.view').forEach(v=>v.classList.remove('active'));$('#view-'+view)?.classList.add('active');const group=navGroup(view);$$('.navbtn').forEach(b=>b.classList.toggle('active',b.dataset.view===group));$('#bottomnav').style.display='flex';$('#fab').style.display=(view==='stats'||view==='settings')?'none':'block';updatePageIntro(view);v68ShowLoading(view);try{await v68EnsureViewData(view);renderCurrentViewV68(view);persistUIState()}catch(e){v68LogError('go:'+view,e);v68EnterSafeMode(e)}setTimeout(()=>window.scrollTo({top:scrollPositions[view]||0,behavior:'instant'}),0)}
function v68ShowLoading(view){const el=$('#view-'+view);if(el)el.innerHTML='<div class="v68-loading"><span></span><p>正在读取本地论文数据…</p></div>'}
function v68Back(){const last=v68NavStack.pop();if(!last)return;if(last.resourceTab)resourceTab=last.resourceTab;if(last.statsRange){statsRange=last.statsRange;statsAnchor=last.statsAnchor}scrollPositions[last.view]=last.scroll||0;go(last.view,{fromBack:true})}
function v68UpdateBackButton(){const b=$('#v68BackBtn');if(b)b.classList.toggle('show',v68NavStack.length>0)}

async function setResourceGroup(g){resourceGroup=g;resourceTab={materials:'literature',execution:'todos',delivery:'versions'}[g];resourceFilter=['todos','feedback','figures','defense'].includes(resourceTab)?'active':'all';resourceListLimit=36;persistUIState();await v68EnsureResourceData();renderResources()}
async function setResourceTab(tab){resourceTab=tab;resourceGroup=resourceGroupForTab(tab);resourceFilter=['todos','feedback','figures','defense'].includes(tab)?'active':'all';resourceListLimit=36;persistUIState();await v68EnsureResourceData();renderResources()}
window.setResourceFilter=function(v){resourceFilter=v;resourceListLimit=36;persistUIState();renderResources()};


function v68WorkerRequest(worker,op,payload,timeout=15000){return new Promise((res,rej)=>{if(!worker)return rej(new Error('Worker unavailable'));const id='w'+(++v68WorkerSeq),t=setTimeout(()=>{worker.removeEventListener('message',on);rej(new Error('Worker timeout'))},timeout),on=e=>{if(e.data?.id!==id)return;clearTimeout(t);worker.removeEventListener('message',on);e.data.ok?res(e.data.result||e.data):rej(new Error(e.data.error||'Worker failed'))};worker.addEventListener('message',on);worker.postMessage({id,op,payload})})}
function v68InitWorkers(){try{v68AnalyticsWorker=new Worker('./analytics-worker.js')}catch(e){v68LogError('analytics-worker-init',e)}try{v68ImageWorker=new Worker('./image-worker.js')}catch(e){v68LogError('image-worker-init',e)}}
function v68Tokenize(text){const s=String(text||'').toLowerCase().normalize('NFKC').replace(/\s+/g,' ').trim(),set=new Set();for(const w of s.split(/[\s,，。；;:：/\\|()（）\[\]{}]+/).filter(Boolean)){set.add(w);if(w.length>=2)for(let i=0;i<w.length-1;i++)set.add(w.slice(i,i+2));if(w.length>=3)for(let i=0;i<w.length-2;i++)set.add(w.slice(i,i+3))}return [...set].slice(0,80)}
async function v68AssembleFullState(){const s=await v68Get('config','settings'),u=await v68Get('config','ui'),raw={settings:s?.value||state.settings,ui:u?.value||state.ui};for(const k of V68_STORE_KEYS)raw[k]=await v68GetAll(k);return normalize(raw)}
async function v68RebuildSearchIndex(){
 if(!v68DbReady)return;const full=await v68AssembleFullState();let entries;
 try{entries=await v68WorkerRequest(v68AnalyticsWorker,'searchIndex',full,25000)}catch(e){entries=[];const push=(module,id,title,text,updatedAt='')=>entries.push({id:`${module}:${id}`,module,recordId:id,title:String(title||''),text:String(text||''),normalized:String(`${title||''} ${text||''}`).toLowerCase(),updatedAt});(full.literature||[]).forEach(x=>push('文献',x.id,x.title,[x.authors,x.doi,x.tags,x.notes].join(' '),x.updatedAt));(full.problems||[]).forEach(x=>push('问题',x.id,x.title,[x.description,x.resolution,x.lesson].join(' '),x.updatedAt));(full.todos||[]).forEach(x=>push('待办',x.id,x.title,x.notes,x.updatedAt))}
 const metas=await v68GetAll('imagesMeta');for(const x of metas)entries.push({id:`本地图片:${x.id}`,module:'本地图片',recordId:x.id,title:x.name||'图片',text:[x.ownerLabel,x.ownerType,x.hash].join(' '),normalized:String(`${x.name||''} ${x.ownerLabel||''}`).toLowerCase(),updatedAt:String(x.createdAt||'')});
 const tx=v68db.transaction('searchIndex','readwrite'),st=tx.objectStore('searchIndex');st.clear();for(const e of entries){e.tokens=v68Tokenize(`${e.title} ${e.text}`);st.put(e)}await v68TxDone(tx);await v68Put('meta',{key:'searchIndex',value:{builtAt:nowStamp(),count:entries.length,strategy:'full-rebuild-v681'}})
}
async function v68SearchDB(q,module='all'){const query=String(q||'').trim().toLowerCase().normalize('NFKC');if(!query)return[];let candidates=[];const toks=v68Tokenize(query),token=toks.sort((a,b)=>b.length-a.length)[0];try{if(token)candidates=await v68Query('searchIndex','tokens',IDBKeyRange.only(token),'prev');else candidates=await v68GetAll('searchIndex')}catch(e){candidates=await v68GetAll('searchIndex')}return candidates.filter(x=>(module==='all'||x.module===module)&&String(x.normalized||'').includes(query)).sort((a,b)=>String(b.updatedAt||'').localeCompare(String(a.updatedAt||''))).slice(0,80)}
function globalSearch(){ensureCurrentState();const hist=state.ui.searchHistory||[];openSheet(`<h3>全局搜索</h3><div class="search-tools"><input id="globalQ" placeholder="搜索论文全部记录……" oninput="runGlobalSearchV68()"><select id="globalModule" onchange="runGlobalSearchV68()"><option value="all">全部模块</option>${['章节','小节','章节任务','写作记录','写作路线','问题','文献','修改','待办','会议','图表','节点','版本','答辩','本地图片'].map(x=>`<option>${x}</option>`).join('')}</select></div>${hist.length?`<div class="search-history">${hist.slice(0,6).map((q,i)=>`<button onclick="useSearchHistory(${i})">${esc(q)}</button>`).join('')}</div>`:''}<div class="backup-note">V6.8.2 使用增量 IndexedDB 搜索索引，不需要先把所有历史记录加载到当前页面。</div><div id="searchResults"><div class="empty">输入关键词即可检索全部论文记录。</div></div>`);setTimeout(()=>$('#globalQ')?.focus(),100)}
function v68Highlight(s,q){const safe=esc(s||''),needle=String(q||'').replace(/[.*+?^${}()|[\]\\]/g,'\\$&');if(!needle)return safe;return safe.replace(new RegExp(`(${needle})`,'ig'),'<mark class="search-hit">$1</mark>')}
async function runGlobalSearchV68(){const q=$('#globalQ')?.value.trim()||'',module=$('#globalModule')?.value||'all',box=$('#searchResults');if(!box)return;if(!q){box.innerHTML='<div class="empty">输入关键词即可检索全部论文记录。</div>';return}box.innerHTML='<div class="empty">正在查询本地索引……</div>';const r=await v68SearchDB(q,module);state.ui.searchHistory=[q,...(state.ui.searchHistory||[]).filter(x=>x!==q)].slice(0,8);persistUIState();box.innerHTML=r.length?r.map(x=>`<div class="card" onclick="v68OpenSearchResult('${esc(x.module)}','${esc(x.recordId)}')"><div class="row"><div class="title">${v68Highlight(x.title,q)}</div><span class="chip blue">${esc(x.module)}</span></div><div class="meta">${v68Highlight(String(x.text||'').slice(0,130),q)}</div></div>`).join(''):'<div class="empty">没有找到匹配内容。</div>'}
async function v68OpenSearchResult(module,id){closeSheet();const map={文献:['resources','literature','literatureForm'],问题:['problems','', 'problemDetail'],修改:['resources','feedback','feedbackForm'],待办:['resources','todos','todoForm'],会议:['resources','meetings','meetingForm'],图表:['resources','figures','figureForm'],节点:['resources','milestones','milestoneForm'],版本:['resources','versions','versionForm'],答辩:['resources','defense','defenseForm'],写作记录:['stats','', 'writingLogForm'],写作路线:['chapters','', 'writingRouteForm']};if(module==='本地图片'){await go('resources');resourceTab='images';await v68EnsureResourceData();renderResources();setTimeout(()=>previewStoredImageV68(id),80);return}if(module==='章节'||module==='小节'||module==='章节任务'){const cid=String(id).split('::')[0];await go('chapters');setTimeout(()=>chapterDetail(cid),60);return}const m=map[module];if(!m)return;if(m[1])resourceTab=m[1];await go(m[0]);setTimeout(()=>window[m[2]]?.(id),70)}

async function v68ProcessImageMain(blob,max=420,quality=.78){const hash=await crypto.subtle.digest('SHA-256',await blob.arrayBuffer()).then(b=>[...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join(''));let thumbnail=null;try{const bm=await createImageBitmap(blob),scale=Math.min(1,max/Math.max(bm.width,bm.height)),w=Math.max(1,Math.round(bm.width*scale)),h=Math.max(1,Math.round(bm.height*scale)),c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(bm,0,0,w,h);bm.close();thumbnail=await new Promise(r=>c.toBlob(r,'image/jpeg',quality))}catch(e){}return {hash,thumbnail}}
async function v68ProcessImage(blob){try{const id='img'+(++v68WorkerSeq);return await new Promise((res,rej)=>{if(!v68ImageWorker)return rej(new Error('no image worker'));const t=setTimeout(()=>{v68ImageWorker.removeEventListener('message',on);rej(new Error('image worker timeout'))},20000),on=e=>{if(e.data?.id!==id)return;clearTimeout(t);v68ImageWorker.removeEventListener('message',on);e.data.ok?res({hash:e.data.hash,thumbnail:e.data.thumbnail||null}):rej(new Error(e.data.error))};v68ImageWorker.addEventListener('message',on);v68ImageWorker.postMessage({id,blob,max:420,quality:.78})})}catch(e){return v68ProcessImageMain(blob)}}
async function storeImageFiles(files,ownerType='library',ownerId='',ownerLabel='',mode='optimized'){
 if(!files?.length)return 0;await openV68DB();const baseStats=await v681EnsureImageStats();let n=0,skipped=0,newBytes=0,newThumbBytes=0;const newMetas=[];
 for(const f of files){if(!f.type?.startsWith('image/'))continue;let original=f;if(mode==='optimized'&&f.size>1800000){try{const p=await v68ProcessImageMain(f,2200,.84);if(p.thumbnail&&p.thumbnail.size<f.size)original=new File([p.thumbnail],f.name.replace(/\.[^.]+$/,'.jpg'),{type:'image/jpeg'})}catch(e){}}
  const processed=await v68ProcessImage(original),existing=processed.hash?await v68Query('imagesMeta','hash',IDBKeyRange.only(processed.hash),'next',1):[];if(existing.length){skipped++;continue}const id=uid(),meta={id,name:original.name||f.name||`图片-${id}`,type:original.type,size:original.size||0,originalSize:f.size||0,ownerType,ownerId,ownerLabel,createdAt:Date.now(),hash:processed.hash||'',thumbSize:processed.thumbnail?.size||0};await v68Put('imagesMeta',meta);await v68Put('imageBlobs',{id,blob:original,thumbnail:processed.thumbnail||null});newMetas.push(meta);n++;newBytes+=Number(meta.size||0);newThumbBytes+=Number(meta.thumbSize||0)}
 if(n){v681ImageStats={count:Number(baseStats.count||0)+n,bytes:Number(baseStats.bytes||0)+newBytes,thumbBytes:Number(baseStats.thumbBytes||0)+newThumbBytes,updatedAt:nowStamp()};await v68Put('meta',{key:'imageStats',value:v681ImageStats});for(const meta of newMetas)await v681UpsertImageSearch(meta)}
 await v68UpdateCounts();if(n||skipped)showToast(`已保存 ${n} 张${skipped?` · 跳过重复 ${skipped} 张`:''}`);return n
}
async function v681RecomputeImageStats(){const arr=await v68GetAll('imagesMeta'),value={count:arr.length,bytes:arr.reduce((s,x)=>s+Number(x.size||0),0),thumbBytes:arr.reduce((s,x)=>s+Number(x.thumbSize||0),0),updatedAt:nowStamp()};v681ImageStats=value;await v68Put('meta',{key:'imageStats',value});return value}
async function v681EnsureImageStats(){if(v681ImageStats)return v681ImageStats;const x=await v68Get('meta','imageStats');return x?.value?(v681ImageStats=x.value):v681RecomputeImageStats()}
async function v681AdjustImageStats({recompute=false,countDelta=0,bytesDelta=0,thumbDelta=0}={}){if(recompute)return v681RecomputeImageStats();const s=await v681EnsureImageStats();v681ImageStats={count:Math.max(0,Number(s.count||0)+countDelta),bytes:Math.max(0,Number(s.bytes||0)+bytesDelta),thumbBytes:Math.max(0,Number(s.thumbBytes||0)+thumbDelta),updatedAt:nowStamp()};await v68Put('meta',{key:'imageStats',value:v681ImageStats});return v681ImageStats}
async function v681UpsertImageSearch(meta){if(!meta?.id)return;const e={id:`本地图片:${meta.id}`,module:'本地图片',recordId:meta.id,title:meta.name||'图片',text:[meta.ownerLabel,meta.ownerType,meta.hash].join(' '),normalized:String(`${meta.name||''} ${meta.ownerLabel||''}`).toLowerCase().normalize('NFKC'),updatedAt:String(meta.createdAt||'')};e.tokens=v68Tokenize(`${e.title} ${e.text}`);await v68Put('searchIndex',e);await v681RefreshSearchMeta()}

async function imageLibrary(ownerType='',ownerId='',ownerLabel=''){openSheet(`<h3>本地图片资料库</h3><div class="notice">V6.8.2 将图片元数据、缩略图和原图分开保存。列表只读取缩略图，打开详情时才读取原图。</div><div class="field"><label>选择图片</label><input id="imageUpload" type="file" accept="image/*" multiple></div><div class="field"><label>保存方式</label><select id="imageSaveMode"><option value="optimized">优化保存（大图自动压缩，推荐）</option><option value="original">保存原图</option></select></div><div class="actions"><button class="btn primary" onclick="uploadImagesFromSheet('${esc(ownerType)}','${esc(ownerId)}','${esc(ownerLabel)}')">保存到本机</button></div><div id="imageList"><div class="empty">正在读取图片……</div></div>`);await renderImageLibrary(ownerType,ownerId)}
async function uploadImagesFromSheet(ownerType='',ownerId='',ownerLabel=''){const files=$('#imageUpload')?.files;if(!files?.length)return alert('请先选择图片');await storeImageFiles([...files],ownerType||'library',ownerId,ownerLabel,$('#imageSaveMode')?.value||'optimized');await renderImageLibrary(ownerType,ownerId)}
async function v68ImageRows(ownerType='',ownerId='',limit=60){if(ownerType&&ownerId)return v68Query('imagesMeta','ownerCreatedAt',IDBKeyRange.bound([ownerType,ownerId,0],[ownerType,ownerId,Number.MAX_SAFE_INTEGER]),'prev',limit);if(ownerType)return v68Query('imagesMeta','ownerTypeCreatedAt',IDBKeyRange.bound([ownerType,0],[ownerType,Number.MAX_SAFE_INTEGER]),'prev',limit);return v68Query('imagesMeta','createdAt',null,'prev',limit)}
async function v68AttachThumbs(arr,prefix='thumb-'){for(const x of arr){const el=$(`#${prefix}${x.id}`);if(!el)continue;const rec=await v68Get('imageBlobs',x.id),blob=rec?.thumbnail||null;if(blob){const u=URL.createObjectURL(blob);el.innerHTML=`<img src="${u}" alt="">`;setTimeout(()=>URL.revokeObjectURL(u),45000)}}}
async function renderImageLibrary(ownerType='',ownerId=''){const box=$('#imageList');if(!box)return;const arr=await v68ImageRows(ownerType,ownerId,60);box.innerHTML=arr.length?arr.map(x=>`<div class="image-row"><div class="image-thumb" id="thumb-${x.id}" onclick="previewStoredImageV68('${x.id}')"></div><div class="image-info" onclick="previewStoredImageV68('${x.id}')"><b>${esc(x.name)}</b><span>${formatBytes(x.size||0)} · 缩略图 ${formatBytes(x.thumbSize||0)} · ${esc(x.ownerLabel||x.ownerType||'资料库')}</span></div><button class="tiny-btn" onclick="deleteStoredImage('${x.id}')">删除</button></div>`).join(''):'<div class="empty">还没有本地图片。</div>';await v68AttachThumbs(arr)}
async function renderResourceImageList(){const target=$('#resourceImageList');if(!target)return;const arr=await v68ImageRows('', '',60),stats=await v681EnsureImageStats();target.innerHTML=`<div class="row" style="margin-bottom:8px"><div class="meta">${stats.count} 张 · ${formatBytes(stats.bytes)} · Cursor 分页只读缩略图</div><button class="tiny-btn" onclick="imageSpaceManagerV68()">空间管理</button></div>`+(arr.length?arr.map(x=>`<div class="image-row"><div class="image-thumb" id="rthumb-${x.id}" onclick="previewStoredImageV68('${x.id}')"></div><div class="image-info" onclick="previewStoredImageV68('${x.id}')"><b>${esc(x.name)}</b><span>${formatBytes(x.size||0)} · ${esc(x.ownerLabel||x.ownerType||'资料库')}</span></div><button class="tiny-btn" onclick="deleteStoredImage('${x.id}')">删除</button></div>`).join(''):'<div class="empty">还没有图片。点“+ 图片”从相册或文件中选择。</div>');await v68AttachThumbs(arr,'rthumb-')}
async function previewStoredImageV68(id){const meta=await v68Get('imagesMeta',id),rec=await v68Get('imageBlobs',id);if(!meta||!rec?.blob)return alert('图片原图无法读取');const u=URL.createObjectURL(rec.blob);openSheet(`<h3>${esc(meta.name)}</h3><img class="image-preview" src="${u}"><div class="meta" style="margin-top:8px">${formatBytes(meta.size||rec.blob.size)} · SHA-256 ${esc((meta.hash||'').slice(0,16))}… · ${esc(meta.ownerLabel||meta.ownerType||'图片资料库')}</div><div class="actions"><button class="btn soft" onclick="closeSheet()">返回</button><button class="btn danger" onclick="deleteStoredImage('${id}')">移入回收站</button></div>`);setTimeout(()=>URL.revokeObjectURL(u),120000)}
async function deleteStoredImage(id){if(!confirm('删除这张本地图片吗？'))return;const meta=await v68Get('imagesMeta',id),rec=await v68Get('imageBlobs',id);if(!meta)return;await v68Put('trash',{id:uid(),module:'storedImageV68',item:meta,context:{blob:rec?.blob||null,thumbnail:rec?.thumbnail||null},deletedAt:Date.now(),label:`图片 · ${meta.name}`});await v68Delete('imagesMeta',id);await v68Delete('imageBlobs',id);await v68Delete('searchIndex',`本地图片:${id}`);await v681AdjustImageStats({countDelta:-1,bytesDelta:-Number(meta.size||0),thumbDelta:-Number(meta.thumbSize||0)});await v681RefreshSearchMeta();await v68UpdateCounts();showToast('图片已移入回收站');if($('#imageList'))renderImageLibrary();if($('#resourceImageList'))renderResourceImageList()}
async function getImageCount(){return v68Count('imagesMeta')}
async function imageSpaceManagerV68(){for(const k of ['figures','meetings','problems','feedback','literature'])if(!v68FullLoaded.has(k))await v68LoadStore(k,{full:true});const images=await v68GetAll('imagesMeta'),trash=await v68GetAll('trash'),st=await v682StorageStatus({includeBreakdown:true}),orphans=images.filter(x=>!imageOwnerExistsV68(x));openSheet(`<h3>图片与存储空间</h3><div class="health-grid"><div class="health-tile"><b>${images.length}</b><span>当前图片</span></div><div class="health-tile"><b>${formatBytes(st.imageBytes)}</b><span>图片+缩略图</span></div><div class="health-tile"><b>${formatBytes(st.snapshotBytes)}</b><span>快照估算</span></div><div class="health-tile ${st.level==='normal'?'':st.level==='critical'?'bad':'warn'}"><b>${st.ratioText}</b><span>浏览器存储使用率</span></div></div>${v682StorageBarHTML(st)}<div class="backup-note">孤立图片 ${orphans.length} 张 · 回收站 ${trash.length} 项。${v682StorageAdvice(st)}</div><div class="settings-grid"><button class="pill-btn" onclick="v68AdoptOrphans()">整理孤立图片</button><button class="pill-btn" onclick="v68DeleteOrphans()">清理孤立图片</button><button class="pill-btn" onclick="snapshotManager()">管理快照</button><button class="pill-btn" onclick="v682StorageProtectionCenter()">长期存储保护</button></div>`)}
function imageOwnerExistsV68(x){if(!x?.ownerType||x.ownerType==='library')return true;const map={figures:'figures',meetings:'meetings',problems:'problems',feedback:'feedback',literature:'literature'};const k=map[x.ownerType];if(!k)return true;return (state[k]||[]).some(v=>v.id===x.ownerId)}
async function v68AdoptOrphans(){for(const k of ['figures','meetings','problems','feedback','literature'])if(!v68FullLoaded.has(k))await v68LoadStore(k,{full:true});const a=(await v68GetAll('imagesMeta')).filter(x=>!imageOwnerExistsV68(x));for(const x of a){x.ownerType='library';x.ownerId='';x.ownerLabel='图片资料库';await v68Put('imagesMeta',x)}showToast(`已整理 ${a.length} 张图片`);imageSpaceManagerV68()}
async function v68DeleteOrphans(){for(const k of ['figures','meetings','problems','feedback','literature'])if(!v68FullLoaded.has(k))await v68LoadStore(k,{full:true});const a=(await v68GetAll('imagesMeta')).filter(x=>!imageOwnerExistsV68(x));if(!a.length)return showToast('没有孤立图片');if(!confirm(`将 ${a.length} 张孤立图片移入回收站，确定吗？`))return;for(const x of a)await deleteStoredImage(x.id);imageSpaceManagerV68()}
function figureForm(id){if(!v68FullLoaded.has('figures')){v68LoadStore('figures',{full:true}).then(()=>figureForm(id));return}const x=state.figures.find(v=>v.id===id)||{kind:'图',no:'',title:'',chapter:'',status:'待制作',captionChecked:false,citedInText:false,sourceChecked:false,insertedInText:false,englishCaptionChecked:false,fileName:'',sourcePath:'',notes:''},rid=id||uid();openSheet(`<h3>${id?'编辑图表':'新增图表'}</h3><div class="form2"><div class="field"><label>类型</label><select id="f-kind">${['图','表'].map(s=>`<option ${x.kind===s?'selected':''}>${s}</option>`)}</select></div><div class="field"><label>编号</label><input id="f-no" value="${esc(x.no||'')}" placeholder="图4-1"></div></div><div class="field"><label>标题</label><input id="f-title" value="${esc(x.title||'')}"></div><div class="field"><label>所属章节</label><input id="f-chapter" value="${esc(x.chapter||'')}"></div><div class="field"><label>状态</label><select id="f-status">${['待制作','制作中','待修改','已完成'].map(s=>`<option ${x.status===s?'selected':''}>${s}</option>`)}</select></div><div class="form2"><div class="field"><label>文件名</label><input id="f-file" value="${esc(x.fileName||'')}"></div><div class="field"><label>源文件路径</label><input id="f-sourcepath" value="${esc(x.sourcePath||'')}"></div></div><div class="field-checks"><label class="field-check"><input id="f-caption" type="checkbox" ${x.captionChecked?'checked':''}>中文图题</label><label class="field-check"><input id="f-engcaption" type="checkbox" ${x.englishCaptionChecked?'checked':''}>英文图题</label><label class="field-check"><input id="f-inserted" type="checkbox" ${x.insertedInText?'checked':''}>已插正文</label><label class="field-check"><input id="f-cited" type="checkbox" ${x.citedInText?'checked':''}>正文已引用</label><label class="field-check"><input id="f-sourcecheck" type="checkbox" ${x.sourceChecked?'checked':''}>来源已核对</label></div><div class="field"><label>备注</label><textarea id="f-notes">${esc(x.notes||'')}</textarea></div><div class="actions">${id?`<button class="btn danger" onclick="removeItem('figures','${id}')">删除</button>`:''}<button class="btn soft" onclick="imageLibrary('figures','${rid}','${esc(x.title||'新图表')}')">本地图片</button><button class="btn primary" onclick="saveFigure('${id||''}')">保存</button></div>`)}


/* Draft protection */
const v68BaseOpenSheet=openSheet,v68BaseCloseSheet=closeSheet;
function v68DraftEligible(){const h=$('#sheetContent h3')?.textContent||'';return !!h&&!/^编辑/.test(h)&&!/(搜索|回收站|快照|健康|空间|说明|切换论文阶段)/.test(h)&&$('#sheetContent .actions')}
function v68DraftKey(){const h=($('#sheetContent h3')?.textContent||'表单').replace(/\s+/g,' ').slice(0,80);return `draft:${h}`}
function v68CollectForm(){const data={};$$('#sheetContent input,#sheetContent textarea,#sheetContent select').forEach(el=>{if(!el.id)return;data[el.id]={value:el.value,checked:!!el.checked,type:el.type||el.tagName}});return data}
function v68ApplyDraft(data){for(const [id,v] of Object.entries(data||{})){const el=document.getElementById(id);if(!el)continue;if(el.type==='checkbox'||el.type==='radio')el.checked=!!v.checked;else el.value=v.value??'';el.dispatchEvent(new Event('change',{bubbles:true}))}}
async function v68LoadDraftPrompt(){if(!v68DraftEligible())return;v68ActiveDraftKey=v68DraftKey();const d=await v68Get('drafts',v68ActiveDraftKey);if(!d?.data||Date.now()-Number(d.savedAt||0)>7*86400000)return;const box=document.createElement('div');box.className='draft-banner';box.innerHTML=`<div><b>发现未保存草稿</b><span>${new Date(d.savedAt).toLocaleString('zh-CN')}</span></div><div><button id="draftDiscard">忽略</button><button id="draftRestore">继续填写</button></div>`;$('#sheetContent')?.prepend(box);$('#draftRestore').onclick=()=>{v68ApplyDraft(d.data);box.remove();showToast('草稿已恢复')};$('#draftDiscard').onclick=async()=>{await v68Delete('drafts',v68ActiveDraftKey);box.remove()}}
function v68ScheduleDraft(){if(!v68DraftEligible())return;v68ActiveDraftKey=v68DraftKey();clearTimeout(v68ScheduleDraft.t);v68ScheduleDraft.t=setTimeout(()=>v68Put('drafts',{id:v68ActiveDraftKey,data:v68CollectForm(),savedAt:Date.now(),title:$('#sheetContent h3')?.textContent||''}).catch(e=>v68LogError('draft-save',e)),500)}
openSheet=function(html){v68BaseOpenSheet(html);v68ActiveDraftKey='';setTimeout(()=>{v68LoadDraftPrompt().catch(()=>{});$('#sheetContent')?.addEventListener('input',v68ScheduleDraft);$('#sheetContent')?.addEventListener('change',v68ScheduleDraft)},0)};
closeSheet=function(){v68BaseCloseSheet()};
async function v68ClearActiveDraft(){if(v68ActiveDraftKey){try{await v68Delete('drafts',v68ActiveDraftKey)}catch(e){}v68ActiveDraftKey=''}}

/* Full snapshots remain full-state on purpose: simpler and safer than delta chains for a thesis app. */
maybeSnapshot=async function(force=false,label=''){
 try{await openV68DB();const arr=(await v68GetAll('snapshots')).sort((a,b)=>b.ts-a.ts),now=Date.now(),last=arr[0]?.ts||0;if(force||now-last>6*3600000){const full=await v68AssembleFullState();await v68Put('snapshots',{id:uid(),ts:now,label:label||(force?'手动快照':'自动快照'),state:full,kind:force?'manual':'auto',schema:2});const all=(await v68GetAll('snapshots')).sort((a,b)=>b.ts-a.ts);for(const x of all.slice(12))await v68Delete('snapshots',x.id)}}catch(e){v68LogError('snapshot',e)}
};
restoreSnapshotV66=async function(id){if(!confirm('恢复该快照会覆盖当前状态，确定吗？'))return;await maybeSnapshot(true,'恢复快照前自动备份');const x=await v68Get('snapshots',id);if(!x?.state)return alert('未找到该快照');await v68WriteFullState(x.state);await v68LoadConfig();await v68LoadHomeData();closeSheet();showToast('已恢复快照');go('home',{replace:true})};
restoreSnapshot=restoreSnapshotV66;

/* Trash restore adapted to normalized stores and image/blob split */
restoreTrash=async function(id){const e=await v68Get('trash',id);if(!e)return;const m=e.module,item=e.item,ctx=e.context||{};try{
 if(m==='storedImageV68'){await v68Put('imagesMeta',item);await v68Put('imageBlobs',{id:item.id,blob:ctx.blob||null,thumbnail:ctx.thumbnail||null})}
 else if(m==='storedImage'&&ctx.image){await v68ImportLegacyImage(ctx.image)}
 else if(m==='sections'||m==='chapterTasks'){const cid=ctx.parentChapterId;if(!v68FullLoaded.has('chapters'))await v68LoadStore('chapters',{full:true});const c=state.chapters.find(x=>x.id===cid);if(c){const key=m==='sections'?'sections':'tasks';c[key]=c[key]||[];if(!c[key].some(x=>x.id===item.id))c[key].push(item);c.updatedAt=nowStamp();v68Loaded.add('chapters');await v68PersistLoaded()}}
 else if(V68_STORE_KEYS.includes(m)){if(v68Loaded.has(m)&&!state[m].some(x=>x.id===item.id))state[m].push(item);await v68Put(m,item);if(m==='writingLogs'){if(!v68FullLoaded.has('chapters'))await v68LoadStore('chapters',{full:true});applyWritingDelta(item.chapterId,item.sectionId,Number(item.words||0));await v68ReplaceStore('chapters',state.chapters)}}
 await v68Delete('trash',id);if(m==='storedImageV68'){await v681AdjustImageStats({countDelta:1,bytesDelta:Number(item.size||0),thumbDelta:Number(item.thumbSize||0)});await v681UpsertImageSearch(item)}else if(V68_STORE_KEYS.includes(m))await v681UpsertSearchForRecord(m,item);await v68UpdateCounts();showToast(m.startsWith('storedImage')?'图片已恢复':'已从回收站恢复');closeSheet();renderAll()
 }catch(err){v68LogError('trash-restore',err);alert('恢复失败，原回收站项目仍保留。')}};

function v68DataURLToBlob(data,type='application/octet-stream'){const b64=String(data||'').split(',')[1]||'',bin=atob(b64),u8=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)u8[i]=bin.charCodeAt(i);return new Blob([u8],{type})}
function v68BlobToDataURL(blob){return new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=()=>rej(r.error);r.readAsDataURL(blob)})}
async function v68Sha256Text(text){const dig=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text));return [...new Uint8Array(dig)].map(x=>x.toString(16).padStart(2,'0')).join('')}
async function v68BackupBody(){const full=await v68AssembleFullState(),metas=await v68GetAll('imagesMeta'),imageData=[];for(const m of metas){const rec=await v68Get('imageBlobs',m.id);imageData.push({meta:m,blob:rec?.blob?await v68BlobToDataURL(rec.blob):null,blobType:rec?.blob?.type||'',thumbnail:rec?.thumbnail?await v68BlobToDataURL(rec.thumbnail):null,thumbnailType:rec?.thumbnail?.type||''})}return {app:'AcademicCat',format:'acat-full-backup-v2',version:V68_VERSION,schema:2,exportedAt:nowStamp(),state:full,images:imageData,snapshots:await v68GetAll('snapshots'),trash:await encodeBackupValueV67(await v68GetAll('trash'))}}
async function exportCompleteBackupV68(){try{showToast('正在生成并校验完整备份…');await maybeSnapshot(true,'完整备份前快照');const body=await v68BackupBody(),bodyText=JSON.stringify(body),hash=await v68Sha256Text(bodyText),payload={...body,integrity:{algorithm:'SHA-256',hash}},text=JSON.stringify(payload),verify=JSON.parse(text),check=await v68Sha256Text(JSON.stringify(Object.fromEntries(Object.entries(verify).filter(([k])=>k!=='integrity'))));if(check!==hash)throw new Error('backup verification failed');v68LastBackupCheck={at:nowStamp(),hash,bytes:text.length};await v68Put('meta',{key:'lastBackup',value:v68LastBackupCheck});if(typeof v682AfterSuccessfulBackup==='function')v682AfterSuccessfulBackup(v68LastBackupCheck);const blob=new Blob([text],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`学术猫-V6.8.2-完整备份-${iso()}.acatbackup`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);showToast('完整备份已生成并通过 SHA-256 校验')}catch(e){v68LogError('complete-backup',e);alert('完整备份失败，请先检查本机剩余存储空间。')}}
async function v68AnalyzeBackup(raw){const body=Object.fromEntries(Object.entries(raw).filter(([k])=>k!=='integrity')),computed=await v68Sha256Text(JSON.stringify(body)),valid=!raw.integrity?.hash||computed===raw.integrity.hash;let added=0,same=0,overwrite=0,conflict=0;for(const k of V68_STORE_KEYS){const cur=await v68GetAll(k),by=new Map(cur.map(x=>[x.id,x]));for(const x of raw.state?.[k]||[]){const old=by.get(x.id);if(!old)added++;else if(JSON.stringify(old)===JSON.stringify(x))same++;else{overwrite++;if(String(old.updatedAt||'')>String(x.updatedAt||''))conflict++}}}const curImages=new Map((await v68GetAll('imagesMeta')).map(x=>[x.id,x]));for(const x of raw.images||[]){const old=curImages.get(x.meta?.id);if(!old)added++;else if(old.hash&&x.meta?.hash&&old.hash===x.meta.hash)same++;else overwrite++}return {valid,computed,added,same,overwrite,conflict}}
function importCompleteBackupV68(){const inp=document.createElement('input');inp.type='file';inp.accept='.acatbackup,.json,application/json';inp.onchange=()=>{const f=inp.files?.[0];if(!f)return;const r=new FileReader();r.onload=async()=>{try{const raw=JSON.parse(r.result);if(!['acat-full-backup-v2','acat-full-backup'].includes(raw?.format))throw new Error('不是完整备份');showToast('正在做导入差异检查…');const a=await v68AnalyzeBackup(raw);window.__v68PendingBackup=raw;openSheet(`<h3>完整恢复 · 差异检查</h3><div class="health-grid"><div class="health-tile"><b>${a.added}</b><span>新增记录</span></div><div class="health-tile"><b>${a.same}</b><span>相同记录</span></div><div class="health-tile ${a.overwrite?'warn':''}"><b>${a.overwrite}</b><span>将覆盖</span></div><div class="health-tile ${a.conflict?'bad':''}"><b>${a.conflict}</b><span>较新本机记录冲突</span></div></div><div class="backup-note">完整性校验：${a.valid?'通过':'失败'} · 备份版本 ${esc(raw.version||'旧版')} · Schema ${raw.schema||1}。恢复前会再创建当前状态快照。</div><div class="actions"><button class="btn soft" onclick="closeSheet()">取消</button><button class="btn primary" ${a.valid?'':'disabled'} onclick="v68ConfirmRestoreBackup()">确认覆盖恢复</button></div>`)}catch(e){v68LogError('backup-import-parse',e);alert('备份文件无法读取或格式不正确')}};r.readAsText(f)};inp.click()}
async function v68ConfirmRestoreBackup(){const raw=window.__v68PendingBackup;if(!raw)return;await maybeSnapshot(true,'完整恢复前自动快照');try{let source=raw;if(raw.format==='acat-full-backup'){source=await decodeBackupValueV67(raw);await v68WriteFullState(source.state||{});for(const old of source.images||[])await v68ImportLegacyImage(old);for(const x of source.snapshots||[])await v68Put('snapshots',x);for(const x of source.trash||[])await v68Put('trash',x)}else{await v68WriteFullState(raw.state||{});await v68Clear('imagesMeta');await v68Clear('imageBlobs');for(const x of raw.images||[]){await v68Put('imagesMeta',x.meta);await v68Put('imageBlobs',{id:x.meta.id,blob:x.blob?v68DataURLToBlob(x.blob,x.blobType):null,thumbnail:x.thumbnail?v68DataURLToBlob(x.thumbnail,x.thumbnailType):null})}await v68ReplaceStore('snapshots',raw.snapshots||[]);await v68ReplaceStore('trash',await decodeBackupValueV67(raw.trash||[]))}await v68Put('meta',{key:'lastRestore',value:{at:nowStamp(),fromVersion:raw.version||'legacy'}});await v681RecomputeImageStats();await v68RebuildSearchIndex();await v68LoadConfig();await v68LoadHomeData();window.__v68PendingBackup=null;closeSheet();showToast('完整恢复成功');go('home',{replace:true})}catch(e){v68LogError('backup-restore',e);v68EnterSafeMode(e)}}

exportBackup=async function(){try{const full=await v68AssembleFullState(),payload={app:'AcademicCat',version:V68_VERSION,schema:2,exportedAt:nowStamp(),state:full},text=JSON.stringify(payload,null,2),blob=new Blob([text],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`学术猫论文工作台-V6.8.2-文字备份-${iso()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){alert('导出失败')}};
importBackup=function(){const inp=document.createElement('input');inp.type='file';inp.accept='.json,application/json';inp.onchange=()=>{const f=inp.files?.[0];if(!f)return;const r=new FileReader();r.onload=async()=>{try{let v=JSON.parse(r.result);v=v?.state||v;if(!v||typeof v!=='object')throw new Error();if(!confirm('文字备份会覆盖当前文字/流程数据，但不会删除本地图片。继续吗？'))return;await maybeSnapshot(true,'文字导入前自动快照');await v68WriteFullState(v);await v68RebuildSearchIndex();await v68LoadConfig();await v68LoadHomeData();showToast('文字数据导入成功');go('home',{replace:true})}catch(e){alert('备份文件无法读取')}};r.readAsText(f)};inp.click()};
const v68OldExportCSV=window.exportCSV;window.exportCSV=async function(){const old=state;try{state=await v68AssembleFullState();v68OldExportCSV()}finally{state=old}};


async function v68WordConsistency(full){const by={};for(const x of full.writingLogs||[])by[x.chapterId]=(by[x.chapterId]||0)+Number(x.words||0);return (full.chapters||[]).map(c=>({id:c.id,title:c.title,chapterWords:Number(c.currentWords||0),logWords:Number(by[c.id]||0),diff:Number(c.currentWords||0)-Number(by[c.id]||0)})).filter(x=>x.diff!==0)}
function v68FigureNumberIssues(figures=[]){const seen=new Map(),dup=[];for(const x of figures){const n=String(x.no||'').trim();if(!n)continue;if(seen.has(n))dup.push(n);else seen.set(n,x.id)}return [...new Set(dup)]}
async function dataHealthCheckV68(){try{showToast('正在后台检查数据…');const full=await v68AssembleFullState(),worker=await v68WorkerRequest(v68AnalyticsWorker,'health',full,25000).catch(()=>({issues:[],total:0,bad:0,warn:0})),cons=await v68WordConsistency(full),figDup=v68FigureNumberIssues(full.figures),images=await v68Count('imagesMeta'),snaps=await v68Count('snapshots'),drafts=await v68Count('drafts'),st=await v682StorageStatus({includeBreakdown:true}),schema=(await v68Get('meta','schema'))?.value;const warnings=worker.total+cons.length+figDup.length+(st.level==='normal'?0:1)+(st.backupOverdue?1:0)+(st.persistent===false?1:0);openSheet(`<h3>数据健康中心</h3><div class="row"><div><div class="title">${warnings?'发现可检查项目':'数据状态正常'}</div><div class="meta">Schema v${schema?.version||'?'} · Worker 检查 · 数据库按模块分表</div></div><span class="data-badge ${warnings?'warn':''}">${warnings?warnings+' 项提示':'正常'}</span></div><div class="health-grid" style="margin-top:10px"><div class="health-tile"><b>${V68_STORE_KEYS.reduce((sum,k)=>sum+Number(v68Counts[k]||0),0)}</b><span>文字/流程记录</span></div><div class="health-tile"><b>${images}</b><span>本地图片</span></div><div class="health-tile"><b>${snaps}</b><span>完整快照</span></div><div class="health-tile ${st.persistent===false?'warn':''}"><b>${st.persistentLabel}</b><span>长期存储保护</span></div></div>${v682StorageBarHTML(st)}<div class="section-title"><h2>完整性</h2><span class="sub">不自动改数据</span></div>${healthLine('记录 ID / 重复 DOI 等',worker.total||0)}${healthLine('章节字数与写作记录不一致',cons.length)}${healthLine('重复图号 / 表号',figDup.length)}${healthLine('未保存草稿',drafts.length)}${healthLine('完整备份超期',st.backupOverdue?1:0)}<div class="backup-note">最近完整备份：${st.lastBackupAt||'暂无'}${st.lastBackupHash?' · SHA-256 已验证':''}<br>存储：已用 ${formatBytes(st.usage)} / 配额 ${formatBytes(st.quota)} · ${st.ratioText}。<br>图片 ${formatBytes(st.imageBytes)} · 快照约 ${formatBytes(st.snapshotBytes)} · 其他本地数据/缓存约 ${formatBytes(st.otherBytes)}。<br>${v682StorageAdvice(st)}</div>${cons.length?`<div class="section-title"><h2>字数差异</h2><span class="sub">仅显示前 8 章</span></div>${cons.slice(0,8).map(x=>`<div class="section-mini"><div class="title">${esc(x.title)}</div><div class="meta">章节 ${fmt(x.chapterWords)} 字 · 写作记录累计 ${fmt(x.logWords)} 字 · 差 ${fmt(x.diff)} 字</div></div>`).join('')}<button class="pill-btn" style="width:100%" onclick="v68RecalculateChapterWords()">按写作记录重新核算章节字数</button>`:''}<div class="settings-grid"><button class="pill-btn" onclick="v682StorageProtectionCenter()">长期存储保护</button><button class="pill-btn" onclick="exportCompleteBackupV68()">完整备份</button><button class="pill-btn" onclick="snapshotManager()">历史快照</button><button class="pill-btn" onclick="v68ShowErrorLogs()">错误日志</button></div>`)}catch(e){v68LogError('health-check',e);v68EnterSafeMode(e)}}
async function updateStorageStatus(ok=v68DbReady){const el=$('#storageStatus'),pe=$('#persistenceStatus');if(!el&&!pe)return;const st=await v682StorageStatus();const images=await v68Count('imagesMeta').catch(()=>0),snaps=await v68Count('snapshots').catch(()=>0),trash=await v68Count('trash').catch(()=>0);if(el)el.textContent=ok?`Schema v2 正常 · ${st.persistentLabel} · 存储 ${st.ratioText} · 图片 ${images} · 快照 ${snaps} · 回收站 ${trash}`:'安全兼容模式 · 建议先导出备份';if(pe)pe.textContent=`${st.persistentLabel} · 已用 ${formatBytes(st.usage)} / ${formatBytes(st.quota)}${st.backupOverdue?' · 建议完整备份':''}`}
function renderSettings(){const set=state.settings;$('#view-settings').innerHTML=`<div class="settings-page-head"><img src="apple-touch-icon.png"><div><h2>我的</h2><p>论文设置保持简洁，长期存储、备份和数据库安全集中管理。</p></div></div><div class="settings-section"><h3>论文与写作</h3><div class="setting-row" onclick="stagePickerV67()"><div class="left"><div class="name">当前阶段</div><div class="value">${esc(set.currentStage||'正文写作')} · 点按切换</div></div><span class="chev">›</span></div><div class="setting-row" onclick="settingsForm()"><div class="left"><div class="name">论文与时间节点</div><div class="value">${esc(set.thesisTitle)} · ${fmt(set.totalWordGoal)} 字</div></div><span class="chev">›</span></div><div class="setting-row" onclick="quickPrivacySettings()"><div class="left"><div class="name">显示与写作偏好</div><div class="value">每日 ${fmt(set.dailyWordGoal)} 字 · 专注 ${set.focusMinutes} 分钟</div></div><span class="chev">›</span></div></div><div class="settings-section"><h3>数据安全</h3><div class="setting-row" onclick="v682StorageProtectionCenter()"><div class="left"><div class="name">长期存储保护</div><div class="value" id="persistenceStatus">正在检查持久化与空间状态……</div></div><span class="chev">›</span></div><div class="setting-row" onclick="dataHealthCheckV68()"><div class="left"><div class="name">数据健康</div><div class="value" id="storageStatus">正在检查……</div></div><span class="chev">›</span></div><div class="settings-grid"><button class="pill-btn" onclick="exportCompleteBackupV68()">完整备份</button><button class="pill-btn" onclick="importCompleteBackupV68()">完整恢复</button><button class="pill-btn" onclick="trashManager()">回收站</button><button class="pill-btn" onclick="imageLibrary()">图片资料库</button></div></div><details class="settings-section advanced-box"><summary><b>高级与数据管理</b><span>数据库、快照、搜索、离线与诊断</span></summary><div class="advanced-body"><div class="settings-grid"><button class="pill-btn" onclick="manualSnapshot()">立即快照</button><button class="pill-btn" onclick="snapshotManager()">历史快照</button><button class="pill-btn" onclick="imageSpaceManagerV68()">存储空间</button><button class="pill-btn" onclick="globalSearch()">全局搜索</button><button class="pill-btn" onclick="exportBackup()">文字 JSON</button><button class="pill-btn" onclick="importBackup()">导入 JSON</button><button class="pill-btn" onclick="exportCSV()">导出 CSV</button><button class="pill-btn" onclick="requestPersistentStorage()">申请持久存储</button><button class="pill-btn" onclick="checkForUpdate()">检查更新</button><button class="pill-btn" onclick="clearAppCache()">重建离线缓存</button><button class="pill-btn" onclick="v68ShowErrorLogs()">错误日志</button><button class="pill-btn" onclick="v68DatabaseInfo()">数据库信息</button></div></div></details><div class="settings-section"><h3>App 信息</h3><div class="setting-row"><div class="left"><div class="name">学术猫·论文工作台 <span class="version-badge">V6.8.2</span></div><div class="value">长期存储增强版 · 持久化状态 · 空间预警 · 14 天备份提醒 · 配额失败保护</div></div></div><button class="pill-btn" style="width:100%" onclick="showUsageHelp()">使用说明</button></div><details class="settings-section danger-details"><summary>危险操作</summary><div class="advanced-body"><div class="setting-row danger-zone" onclick="resetAllDataV68()"><div class="left"><div class="name" style="color:var(--bad)">清空全部论文数据</div><div class="value">会清除 V6.8.2 数据库内容。建议先生成完整备份。</div></div><span class="chev">›</span></div></div></details>`;updateNetworkBadge();setTimeout(()=>updateStorageStatus(),0)}

function v682IsQuotaError(e){return !!e&&(['QuotaExceededError','NS_ERROR_DOM_QUOTA_REACHED'].includes(e.name)||/quota|storage.*full|disk.*full/i.test(String(e.message||'')))}
function v682Level(ratio){if(ratio>=.90)return'critical';if(ratio>=.85)return'high';if(ratio>=.75)return'notice';return'normal'}
function v682DaysSince(stamp){if(!stamp)return Infinity;const t=Date.parse(String(stamp).replace(' ','T'));return Number.isFinite(t)?Math.floor((Date.now()-t)/86400000):Infinity}
function v682ApproxJsonBytes(value){try{return new Blob([JSON.stringify(value)]).size}catch(e){return 0}}
async function v682StorageStatus({includeBreakdown=false}={}){let persistent=null,supported=!!navigator.storage?.persisted;try{if(supported)persistent=await navigator.storage.persisted()}catch(e){persistent=null}let est={};try{est=await navigator.storage?.estimate?.()||{}}catch(e){}const usage=Number(est.usage||0),quota=Number(est.quota||0),ratio=quota?usage/quota:0,level=v682Level(ratio),img=await v681EnsureImageStats().catch(()=>({bytes:0,thumbBytes:0,count:0})),lastBackup=(await v68Get('meta','lastBackup').catch(()=>null))?.value||null;let snapshotBytes=0;if(includeBreakdown){const snaps=await v68GetAll('snapshots').catch(()=>[]);snapshotBytes=v682ApproxJsonBytes(snaps)}const imageBytes=Number(img.bytes||0)+Number(img.thumbBytes||0),otherBytes=Math.max(0,usage-imageBytes-snapshotBytes),days=v682DaysSince(lastBackup?.at),backupOverdue=!lastBackup||days>=14;return {supported,persistent,persistentLabel:!supported?'浏览器未提供':persistent?'已持久化 ✓':'普通存储',usage,quota,ratio,ratioText:quota?`${Math.round(ratio*100)}%`:'—',level,imageBytes,snapshotBytes,otherBytes,lastBackupAt:lastBackup?.at||'',lastBackupHash:lastBackup?.hash||'',daysSinceBackup:days,backupOverdue,isStandalone:window.matchMedia?.('(display-mode: standalone)')?.matches||navigator.standalone===true}}
function v682StorageAdvice(st){if(st.level==='critical')return'存储已超过 90%，请先完整备份，再清理旧快照、回收站或孤立图片。';if(st.level==='high')return'存储已超过 85%，建议近期整理图片和旧快照，并生成完整备份。';if(st.level==='notice')return'存储已超过 75%，目前仍可使用，但建议开始关注图片与快照占用。';if(st.persistent===false)return'当前仍是普通浏览器存储，建议启用“长期存储保护”，降低系统空间压力时被自动清理的风险。';if(st.backupOverdue)return'本机存储状态正常，但完整备份已超过 14 天，建议导出一份 .acatbackup 到 iCloud Drive。';return'本地存储状态正常。仍建议定期把完整备份保存到 iCloud Drive 或电脑。'}
function v682StorageBarHTML(st){const pct=Math.max(0,Math.min(100,Math.round((st.ratio||0)*100))),cls=st.level==='critical'?'critical':st.level==='high'?'high':st.level==='notice'?'notice':'';return `<div class="storage-meter ${cls}"><div class="storage-meter-head"><span>本机 Web App 存储</span><b>${st.ratioText}</b></div><div class="storage-bar"><span style="width:${pct}%"></span></div><div class="meta">已用 ${formatBytes(st.usage)} · 当前配额 ${formatBytes(st.quota)}</div></div>`}
async function v682RecordPersistenceStatus(ok,source='check'){try{localStorage.setItem('academicCatPersistentEver',ok?'1':localStorage.getItem('academicCatPersistentEver')||'0');localStorage.setItem('academicCatPersistenceLastCheck',String(Date.now()));if(v68DbReady)await v68Put('meta',{key:'persistence',value:{persistent:!!ok,checkedAt:nowStamp(),source,version:V68_VERSION}})}catch(e){}}
function v682AfterSuccessfulBackup(info){try{localStorage.removeItem('academicCatBackupReminderToken');localStorage.setItem('academicCatLastBackupAt',info?.at||nowStamp())}catch(e){}}
async function v682StorageProtectionCenter(reason=''){const st=await v682StorageStatus({includeBreakdown:true}),persistAction=st.supported&&!st.persistent?`<button class="btn primary" onclick="requestPersistentStorage().then(()=>v682StorageProtectionCenter())">启用长期存储保护</button>`:'',reasonNote=reason==='quota'?'<div class="storage-emergency">刚才的保存操作遇到存储配额不足。数据没有被程序主动删除，请先完整备份，再释放空间。</div>':'';openSheet(`<h3>长期存储保护</h3>${reasonNote}<div class="health-grid"><div class="health-tile ${st.persistent===false?'warn':''}"><b>${st.persistentLabel}</b><span>持久存储状态</span></div><div class="health-tile ${st.level==='critical'?'bad':st.level==='normal'?'':'warn'}"><b>${st.ratioText}</b><span>存储使用率</span></div><div class="health-tile"><b>${formatBytes(st.imageBytes)}</b><span>图片+缩略图</span></div><div class="health-tile ${st.backupOverdue?'warn':''}"><b>${st.lastBackupAt?`${st.daysSinceBackup} 天前`:'暂无'}</b><span>最近完整备份</span></div></div>${v682StorageBarHTML(st)}<div class="backup-note">当前配额：${formatBytes(st.quota)}<br>快照约 ${formatBytes(st.snapshotBytes)} · 其他数据库/离线缓存约 ${formatBytes(st.otherBytes)}。<br>${v682StorageAdvice(st)}</div><div class="actions"><button class="btn soft" onclick="exportCompleteBackupV68()">生成完整备份</button>${persistAction}</div><div class="settings-grid"><button class="pill-btn" onclick="imageSpaceManagerV68()">图片与空间</button><button class="pill-btn" onclick="snapshotManager()">历史快照</button><button class="pill-btn" onclick="trashManager()">回收站</button><button class="pill-btn" onclick="dataHealthCheckV68()">数据健康</button></div>`)}
let v682QuotaSheetShown=false;
function v682HandleQuotaExceeded(error,scope=''){try{if(v682QuotaSheetShown)return;v682QuotaSheetShown=true;showToast('本机存储空间不足，已停止当前写入');setTimeout(()=>{v682StorageProtectionCenter('quota').catch(()=>{});v682QuotaSheetShown=false},350)}catch(e){}}
async function v682MaybePromptPersistence(){const st=await v682StorageStatus();if(st.persistent===true){await v682RecordPersistenceStatus(true,'startup');return}if(!st.supported)return;const ever=localStorage.getItem('academicCatPersistentEver')==='1',token=`${V68_VERSION}:${ever?'lost':'new'}`,seen=localStorage.getItem('academicCatPersistencePromptToken');if(seen===token)return;localStorage.setItem('academicCatPersistencePromptToken',token);setTimeout(()=>openSheet(`<h3>${ever?'长期存储保护需要重新确认':'建议启用长期存储保护'}</h3><div class="backup-note">${st.isStandalone?'你正在从 iPhone 主屏幕使用学术猫。':'如果准备长期使用，建议添加到主屏幕后启用。'}启用后，浏览器会尽量把本站数据作为持久存储保留。它仍不能替代完整备份。</div><div class="actions"><button class="btn soft" onclick="closeSheet()">稍后</button><button class="btn primary" onclick="requestPersistentStorage().then(()=>closeSheet())">启用保护</button></div>`),650)}
async function v682MaybeBackupReminder(){const st=await v682StorageStatus();if(!st.backupOverdue)return;const token=st.lastBackupAt||'never';if(localStorage.getItem('academicCatBackupReminderToken')===token)return;localStorage.setItem('academicCatBackupReminderToken',token);setTimeout(()=>showToast(st.lastBackupAt?`完整备份已 ${st.daysSinceBackup} 天未更新，建议备份到 iCloud Drive`:'建议生成第一份完整备份并保存到 iCloud Drive'),1200)}
async function v682CheckStorageWarning(){const st=await v682StorageStatus();if(st.level==='normal')return;const key=`academicCatStorageWarn:${st.level}`,today=iso();if(localStorage.getItem(key)===today)return;localStorage.setItem(key,today);const msg=st.level==='critical'?`本地存储已使用 ${st.ratioText}，请尽快完整备份并清理空间`:st.level==='high'?`本地存储已使用 ${st.ratioText}，建议近期整理图片和快照`:`本地存储已使用 ${st.ratioText}，请关注存储空间`;showToast(msg);if(st.level==='critical')setTimeout(()=>v682StorageProtectionCenter().catch(()=>{}),700)}
async function v682ProtectVersionUpgrade(){try{const rec=await v68Get('meta','schema'),schema=rec?.value||{};if(schema.appVersion&&schema.appVersion!==V68_VERSION&&schema.lastProtectedUpgrade!==V68_VERSION){await maybeSnapshot(true,`V${schema.appVersion} → V${V68_VERSION} 更新保护快照`);schema.lastProtectedUpgrade=V68_VERSION}schema.appVersion=V68_VERSION;schema.lastOpenedAt=nowStamp();await v68Put('meta',{key:'schema',value:schema})}catch(e){v68LogError('version-protection',e)}}
async function v682StartupStorageGuard(){await v682MaybePromptPersistence();await v682CheckStorageWarning();await v682MaybeBackupReminder();updateStorageStatus()}

async function v68DatabaseInfo(){const schema=(await v68Get('meta','schema'))?.value,idx=(await v68Get('meta','searchIndex'))?.value,drafts=await v68Count('drafts'),errs=await v68Count('errorLogs');openSheet(`<h3>数据库信息</h3><div class="detail-block"><b>${V68_DB_NAME}</b><p>Schema v${schema?.version||2} · App V${V68_VERSION}<br>分表：${V68_STORE_KEYS.join('、')}<br>搜索索引：${idx?.count||0} 条 · ${idx?.strategy||'兼容索引'} · ${idx?.builtAt||'未构建'}<br>草稿：${drafts} · 错误日志：${errs}<br>旧数据库保留：${schema?.oldDatabasePreserved?'是':'未知'}</p></div><div class="backup-note">升级失败时，V6.7 的 AcademicCatThesisDBV66 不会被 V6.8.2 自动删除，可用于安全恢复。</div>`)}
async function resetAllDataV68(){if(!confirm('第一次确认：真的要清空全部论文数据吗？'))return;if(!confirm('第二次确认：包括图片、快照、回收站和草稿都会删除。'))return;await exportCompleteBackupV68();for(const s of V68_ALL_STORES)await v68Clear(s);state=normalize(clone(defaults));await v68WriteFullState(state);await v68Put('meta',{key:'schema',value:{version:2,appVersion:V68_VERSION,migratedAt:nowStamp(),fresh:true}});await v68LoadConfig();await v68LoadHomeData();showToast('已清空并重新初始化');go('home',{replace:true})}

async function v68RequestStatsWorker(){try{const result=await v68WorkerRequest(v68AnalyticsWorker,'stats',{writingLogs:state.writingLogs,focusLogs:state.focusLogs},18000);const page=$('#view-stats');if(!page)return;let el=page.querySelector('.v68-worker-summary');if(!el){el=document.createElement('div');el.className='backup-note v68-worker-summary';const head=page.querySelector('.stats-page-head');head?.insertAdjacentElement('afterend',el)}el.textContent=`后台统计 Worker · 当前载入 ${result.sessions} 次写作 · ${fmt(result.words)} 字 · 峰值 ${result.peakDate||'—'} ${result.peakWords?fmt(result.peakWords)+' 字':''}`;}catch(e){v68LogError('stats-worker',e)}}

async function v68LogError(scope,error){try{console.error('[V6.8.2]',scope,error);if(!v68DbReady)return;await v68Put('errorLogs',{id:uid(),scope,message:String(error?.message||error),stack:String(error?.stack||'').slice(0,4000),at:Date.now(),version:V68_VERSION})}catch(e){}}
async function v68ShowErrorLogs(){const arr=(await v68GetAll('errorLogs')).sort((a,b)=>b.at-a.at).slice(0,30);openSheet(`<h3>本机错误日志</h3><div class="notice">不包含论文正文和图片内容，只记录程序模块、时间和错误信息。</div>${arr.map(x=>`<div class="section-mini"><div class="title">${esc(x.scope)}</div><div class="meta">${new Date(x.at).toLocaleString('zh-CN')} · ${esc(x.message)}</div></div>`).join('')||'<div class="empty">暂无错误日志。</div>'}<div class="actions"><button class="btn soft" onclick="v68ExportDiagnostic()">导出诊断 JSON</button><button class="btn danger" onclick="v68ClearErrorLogs()">清空日志</button></div>`)}
async function v68ClearErrorLogs(){await v68Clear('errorLogs');closeSheet();showToast('错误日志已清空')}
async function v68ExportDiagnostic(){const schema=(await v68Get('meta','schema'))?.value,errors=await v68GetAll('errorLogs'),est=await navigator.storage?.estimate?.()||{},diag={app:'AcademicCat',version:V68_VERSION,schema,counts:v68Counts,storage:{usage:est.usage||0,quota:est.quota||0,persistent:navigator.storage?.persisted?await navigator.storage.persisted().catch(()=>null):null},errors:errors.map(x=>({scope:x.scope,message:x.message,at:x.at,version:x.version}))},blob=new Blob([JSON.stringify(diag,null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=`学术猫-V6.8.2-诊断-${iso()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function v68EnterSafeMode(error){v68LogError('safe-mode',error);const home=$('#view-home');$$('.view').forEach(v=>v.classList.remove('active'));home.classList.add('active');currentView='home';home.innerHTML=`<div class="safe-mode"><div class="safe-icon">!</div><h2>数据安全模式</h2><p>V6.8.2 没有继续执行可能损坏数据的操作。旧版数据库仍保留在本机。</p><div class="backup-note">${esc(String(error?.message||error||'数据库初始化失败'))}</div><div class="settings-grid"><button class="pill-btn" onclick="v68RetryBoot()">重新检查数据库</button><button class="pill-btn" onclick="v68RecoverOldDB()">读取 V6.7 旧数据库</button><button class="pill-btn" onclick="importCompleteBackupV68()">从完整备份恢复</button><button class="pill-btn" onclick="v68ExportRecovery()">导出可读取数据</button></div></div>`;$('#bottomnav').style.display='none';$('#fab').style.display='none'}
async function v68RetryBoot(){location.reload()}
async function v68RecoverOldDB(){const old=(await v68ReadOldStore('AcademicCatThesisDBV66','state','main'))?.value;if(!old)return alert('未找到 V6.7 旧数据库');if(!confirm('将 V6.7 旧数据库重新写入 V6.8.2。继续吗？'))return;await v68WriteFullState(old);await v68Put('meta',{key:'schema',value:{version:2,appVersion:V68_VERSION,recoveredAt:nowStamp(),source:'V6.7 old DB'}});location.reload()}
async function v68ExportRecovery(){let data=null;try{data=await v68AssembleFullState()}catch(e){data=v68MainFallbackState()}const blob=new Blob([JSON.stringify({version:V68_VERSION,recovery:true,at:nowStamp(),state:data},null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=`学术猫-V6.8.2-安全模式恢复数据-${iso()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}

async function v68VerifyDatabase(){const s=await v68Get('config','settings'),ch=await v68Count('chapters'),schema=(await v68Get('meta','schema'))?.value;if(!s?.value||!schema||schema.version!==2||ch<1)throw new Error('V6.8.2 数据库完整性校验未通过');return true}
async function v68CheckStorageWarning(){return v682CheckStorageWarning()}


async function initV68App(){if(v68Booting)return;v68Booting=true;try{v68InitWorkers();await openV68DB();await v68MigrateIfNeeded();await v68VerifyDatabase();await v681EnsureImageStats();await v682ProtectVersionUpgrade();await v68LoadConfig();await v68LoadHomeData();if(currentView!=='home')await v68EnsureViewData(currentView);$$('.navbtn').forEach(b=>b.onclick=()=>go(b.dataset.view));renderCurrentViewV68(currentView);updateNetworkBadge();await v68UpdateCounts();updateStorageStatus();registerServiceWorker();maybeSnapshot();v682StartupStorageGuard();const idxCount=await v68Count('searchIndex');if(idxCount===0&&V68_STORE_KEYS.reduce((s,k)=>s+(v68Counts[k]||0),0)>0)setTimeout(()=>v68RebuildSearchIndex().catch(()=>{}),800);else await v681RefreshSearchMeta();if(new URLSearchParams(location.search).get('selftest')==='1')setTimeout(runV68BrowserSelfTest,800)}catch(e){v68EnterSafeMode(e)}finally{v68Booting=false}}

async function runV68BrowserSelfTest(){window.alert=()=>{};window.confirm=()=>true;const result=document.createElement('div');result.id='selfTestResult';result.style.display='none';document.body.appendChild(result);const ok=[];try{await go('chapters');ok.push($('#view-chapters')?.textContent.includes('写作台'));writingLogForm();$('#f-words').value='321';$('#f-min').value='15';$('#f-note').value='V6.8.2 自动化测试';saveWritingLog('');await new Promise(r=>setTimeout(r,250));ok.push((await v68Count('writingLogs'))>=1);await go('resources');resourceTab='literature';await setResourceTab('literature');literatureForm();$('#f-title').value='V6.8.2 Test Literature';saveLiterature('');await new Promise(r=>setTimeout(r,250));ok.push((await v68Count('literature'))>=1);const before=await v68Count('snapshots');await maybeSnapshot(true,'浏览器自动化测试快照');ok.push((await v68Count('snapshots'))>=before+1);await go('stats');ok.push($('#view-stats')?.textContent.includes('统计分析'));await go('settings');ok.push($('#view-settings')?.textContent.includes('V6.8.2'));result.textContent=ok.every(Boolean)?'V682_SELFTEST_PASS':'V682_SELFTEST_FAIL '+JSON.stringify(ok)}catch(e){result.textContent='V682_SELFTEST_FAIL '+String(e?.message||e);v68LogError('selftest',e)}result.style.display='block'}


// Explicit deletion keeps partially loaded stores from resurrecting deleted records.
removeItem=async function(key,id){const item=state[key]?.find(x=>x.id===id);if(!item)return;const trashId=await moveToTrash(key,item);state[key]=state[key].filter(x=>x.id!==id);if(V68_STORE_KEYS.includes(key)){await v68Delete(key,id);await v681DeleteSearchForRecord(key,id)}closeSheet();save();showUndoToast('已移入回收站',()=>restoreTrash(trashId))};
deleteWritingLog=async function(id){const x=state.writingLogs.find(v=>v.id===id);if(!x)return;const trashId=await moveToTrash('writingLogs',x);applyWritingDelta(x.chapterId,x.sectionId,-Number(x.words||0));state.writingLogs=state.writingLogs.filter(v=>v.id!==id);await v68Delete('writingLogs',id);await v681DeleteSearchForRecord('writingLogs',id);await v68ReplaceStore('chapters',state.chapters);closeSheet();save();showUndoToast('写作记录已移入回收站',()=>restoreTrash(trashId))};

initV68App();
